class Importer(ABC):
    def run(self, source: str) -> Report:        # skeleton
        rows = self.parse(source)                # required step
        self.before_store(rows)                  # hook: default no-op
        return self.store(rows)                  # required step

    @abstractmethod
    def parse(self, source: str) -> list[Row]: ...
    @abstractmethod
    def store(self, rows: list[Row]) -> Report: ...
    def before_store(self, rows: list[Row]) -> None: ...
